mapper.select:
SELECT environment_history_id, plan_id, measured_at, temperature, humidity, co2, radiation, light, soil_temperature, soil_moisture, soil_ec, soil_ph FROM greenhouse_environment_history WHERE plan_id = #{planId} AND deleted_at IS NULL
AND measured_at >= #{startDate}
AND DATE_ADD(#{endDate}, INTERVAL 1 DAY) > measured_at
ORDER BY environment_history_id DESC;
